                    state <= 2'b11;
                    green <= 1'b0;
                    yellow <= 1'b1;
                end
            end
            2'b11: begin // yellow light
                if (count == 20_000_000) begin // 2 seconds
                    count <= 0;
                    state <= 2'b00;
                    yellow <= 1'b0;
                    red <= 1'b1;
                end
            end
        endcase
    end
endmodule

