description:
Design a debouncing circuit for a button input. The module captures the input state of a button and generates a stable output (`DB_out`) by filtering out noise or spurious transitions that occur when the button is pressed or released. Using a dual flip-flop mechanism, it ensures that `DB_out` only changes state after a specified stable time period, determined by the parameter `N`, allowing for a clean and reliable interpretation of the button's true state for further processing in digital systems.
module top_module(input 		 clk, n_reset, button_in,				
					  output reg DB_out);

code:
module top_module(input 		 clk, n_reset, button_in,				
					  output reg DB_out);parameter N = 23 ;


	reg  [N-1 : 0]	q_reg;							
	reg  [N-1 : 0]	q_next;
	reg DFF1, DFF2;									
	wire q_add;											
	wire q_reset;


	assign q_reset = (DFF1  ^ DFF2);		
	assign  q_add = ~(q_reg[N-1]);			


	always @ ( q_reset, q_add, q_reg)
		case( {q_reset , q_add})
			2'b00:   q_next <= q_reg;
			2'b01:   q_next <= q_reg + 1;
			default: q_next <= { N {1'b0} };
		endcase 	


	always@(posedge clk)
		if(n_reset ==  1'b1)
		begin
			DFF1 <= 1'b0;
			DFF2 <= 1'b0;
			q_reg <= { N {1'b0} };
		end
		else
		begin
			DFF1 <= button_in;
			DFF2 <= DFF1;
			q_reg <= q_next;
		end


	always@(posedge clk)
		if(q_reg[N-1] == 1'b1)
			DB_out <= DFF2;
		else
			DB_out <= DB_out;

endmodule

