Design a clock generation circuit that takes an input clock signal and produces a lower frequency output clock. The module uses a reset signal to initialize or clear the clock states. It first divides the input clock frequency by 2 to create an intermediate clock signal (CLK2), and then further divides this signal by 2 to generate the final output clock signal (clk_out), which operates at one-fourth the frequency of the input clock.
module top_module(
	input clk_in,
	input reset,
	output clk_out
	);

code:
module top_module(
	input clk_in,
	input reset,
	output clk_out
	);reg CLK2=0;
	reg CLK4=0;

	always @(posedge clk_in) begin 
		if(reset)
			CLK2=0;
		else
			CLK2=~CLK2;
	end
	always @(posedge CLK2) begin 
		if(reset)
			CLK4=0;
		else
			CLK4=~CLK4;
	end

	assign clk_out = CLK4;

endmodule

