description:
Design a circuit to decode PS/2 keyboard data signals. The module captures data bits from a PS/2 interface on the falling edge of the clock and stores them in a data register. When a complete scan code (indicated by a specific bit pattern) is received, it updates the output with the last key pressed and signals that a key was pressed. If the complete code has not been detected, it continues to shift in new data bits.
module top_module( input clk
    , input data
    , output reg key_pressed
    , output reg [7:0] last_pressed
    );

code:
module top_module( input clk
    , input data
    , output reg key_pressed
    , output reg [7:0] last_pressed
    );reg [21:0] data_register;

    always @(negedge clk) begin
        if (data_register[12:2] == 11'b11111100000) begin
            last_pressed <= data_register[21:14];
            key_pressed <= 1;
            data_register <= 0;
        end
        else begin
            key_pressed <= 0;
            data_register <= {data, data_register[21:1]};

        end

    end
endmodule

